import{_ as e,o as a,c as n,ah as i}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Fees and pricing","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/frais-tarification.md","filePath":"src/en/guide/admin/frais-tarification.md"}'),r={name:"en/guide/admin/frais-tarification.md"};function s(o,t,d,c,l,u){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="fees-and-pricing" tabindex="-1">Fees and pricing <a class="header-anchor" href="#fees-and-pricing" aria-label="Permalink to &quot;Fees and pricing&quot;">​</a></h1><p>This section covers defining the amounts families owe (fee structures) and the discounts you can grant on a case-by-case basis. Recording payments themselves is the cashier&#39;s day-to-day job — you only step in here on pricing and discounts.</p><h2 id="fee-structures" tabindex="-1">Fee structures <a class="header-anchor" href="#fee-structures" aria-label="Permalink to &quot;Fee structures&quot;">​</a></h2><p><strong>Payments → Fee Structures</strong> defines, for a given site, department, and academic year, the list of fees owed by students in that department, at that site, for that year. A student with no fee structure matching their site/department/year has no amount calculated.</p><p>To create a fee structure:</p><ol><li>Click <strong>New fee structure</strong>.</li><li>Choose the <strong>Site</strong>, the <strong>Department</strong>, and the <strong>Academic year</strong>.</li><li>Add one or more fee items with <strong>Add a fee item</strong>, filling in the fields below for each.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Label</td><td>e.g. &quot;Tuition&quot;, &quot;Cafeteria&quot;</td></tr><tr><td>Amount</td><td>—</td></tr><tr><td>Optional</td><td>check if the item isn&#39;t owed by default (the family or the cashier enables it case by case)</td></tr><tr><td>Category</td><td>General, Cafeteria, or Transport</td></tr></tbody></table><p>Editing an existing fee structure lets you add, change, or remove items. Deleting a fee structure also permanently deletes all its items.</p><h2 id="discounts" tabindex="-1">Discounts <a class="header-anchor" href="#discounts" aria-label="Permalink to &quot;Discounts&quot;">​</a></h2><p>Discounts aren&#39;t managed on the fee structure itself, but on a specific student&#39;s billing: <strong>Payments → Billing</strong>, search for the student, click <strong>View</strong> to open their billing record.</p><p>On that screen, you alone (as an administrator — the cashier can only record payments) can grant or remove a discount:</p><p>To grant a discount:</p><ol><li>In the &quot;Discounts&quot; section, fill in the <strong>Label</strong> of the discount.</li><li>Choose the <strong>Type</strong>: Fixed amount or Percentage.</li><li>Fill in the matching <strong>Value</strong> and, optionally, a <strong>Reason</strong>.</li><li>Click <strong>Grant discount</strong>.</li></ol><p>Each discount granted shows the name of the administrator who created it. The <strong>Delete</strong> button next to a discount removes it permanently — the student&#39;s outstanding balance is recalculated immediately.</p>',14)])])}const f=e(r,[["render",s]]);export{g as __pageData,f as default};
